"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useTheme } from "next-themes";
import { usePathname } from "next/navigation";
import { generateProceduralPath, type ProceduralPath } from "./procedural-path";
import { useSatellitePaths } from "./use-satellite-paths";
import { useOverlayClipPath } from "./use-overlay-clip-path";

const BLACK = "#000000";
const WHITE = "#FFFFFF";
const BASE_STROKE_WIDTH = 1.5;
const BASE_DASH = 8;
const BASE_GAP = 8;
const BASE_MARKER_RADIUS = 5;
const GLOW_RADIUS_MULTIPLIER = 2.1;
const GLOW_OPACITY = 0.22;
const GLOW_BLUR_STD_DEVIATION = 4;
const LABEL_FONT_SIZE = 10;
const LABEL_OPACITY = 0.45;
const LABEL_OFFSET_X = 8;
const LABEL_OFFSET_Y = 3;
const LABEL_FADE_DURATION_MS = 600;
const INITIAL_LABEL_DISPLAY_MS = 5000;

/** Desktop = precise pointer with real hover support; mobile/tablet otherwise. */
function useIsFineHoverPointer(): boolean {
  const [isFineHoverPointer, setIsFineHoverPointer] = useState(true);
  useEffect(() => {
    const query = window.matchMedia("(hover: hover) and (pointer: fine)");
    const update = () => setIsFineHoverPointer(query.matches);
    update();
    query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, []);
  return isFineHoverPointer;
}

interface Viewport {
  width: number;
  height: number;
}

interface SatelliteVisual {
  name: string;
  path: ProceduralPath;
  dashArray: string;
  radius: number;
}

interface PathAssignment {
  index: number;
  count: number;
}

function buildProceduralPaths(
  assignments: Map<string, PathAssignment>,
  viewport: Viewport,
): Map<string, ProceduralPath> {
  const next = new Map<string, ProceduralPath>();
  assignments.forEach((assignment, name) => {
    // Same seed + assignment -> same relative shape; re-deriving on every
    // viewport change (not just first sighting) keeps both endpoints
    // pinned to the current border instead of drifting off it after a
    // resize, while the (index, count) pairing stays fixed per satellite
    // so an already-animating path never reshapes just because the API's
    // ordering shifted between refreshes.
    next.set(
      name,
      generateProceduralPath({
        seed: name,
        index: assignment.index,
        count: assignment.count,
        width: viewport.width,
        height: viewport.height,
      }),
    );
  });
  return next;
}

function proceduralPathsEqual(a: Map<string, ProceduralPath>, b: Map<string, ProceduralPath>): boolean {
  if (a.size !== b.size) return false;
  let equal = true;
  a.forEach((path, name) => {
    if (b.get(name)?.d !== path.d) equal = false;
  });
  return equal;
}

function buildVisuals(paths: Map<string, ProceduralPath>): SatelliteVisual[] {
  const visuals: SatelliteVisual[] = [];
  let cursor = 0;
  paths.forEach((path, name) => {
    const variant = cursor % 3;
    visuals.push({
      name,
      path,
      dashArray: `${BASE_DASH + variant * 2} ${BASE_GAP + variant * 2}`,
      radius: BASE_MARKER_RADIUS + variant,
    });
    cursor += 1;
  });
  return visuals;
}

function SatelliteLayer({
  visuals,
  viewport,
  color,
  backgroundColor,
  clipPath,
  zIndex,
  layerId,
  registerPath,
  registerMarker,
  registerGlow,
  registerLabel,
  isLabelVisible,
  onMarkerEnter,
  onMarkerLeave,
  onMarkerClick,
}: {
  visuals: SatelliteVisual[];
  viewport: Viewport;
  color: string;
  backgroundColor?: string;
  clipPath?: string | null;
  zIndex: number;
  layerId: string;
  registerPath?: (name: string, node: SVGPathElement | null) => void;
  registerMarker: (name: string, node: SVGCircleElement | null) => void;
  registerGlow?: (name: string, node: SVGCircleElement | null) => void;
  registerLabel?: (name: string, node: SVGTextElement | null) => void;
  isLabelVisible: (name: string) => boolean;
  onMarkerEnter: (name: string) => void;
  onMarkerLeave: (name: string) => void;
  onMarkerClick: (name: string) => void;
}) {
  const glowFilterId = `satellite-glow-${layerId}`;
  return (
    <svg
      viewBox={`0 0 ${viewport.width} ${viewport.height}`}
      aria-hidden="true"
      style={{
        position: "fixed",
        inset: 0,
        zIndex,
        pointerEvents: "none",
        backgroundColor,
        clipPath: clipPath ?? undefined,
      }}
    >
      <defs>
        <filter id={glowFilterId} x="-150%" y="-150%" width="400%" height="400%">
          <feGaussianBlur stdDeviation={GLOW_BLUR_STD_DEVIATION} />
        </filter>
      </defs>
      {visuals.map((visual) => (
        <g key={visual.name} pointerEvents="none">
          <path
            ref={(node) => registerPath?.(visual.name, node)}
            d={visual.path.d}
            fill="none"
            stroke={color}
            strokeWidth={BASE_STROKE_WIDTH}
            strokeDasharray={visual.dashArray}
          />
          <circle
            ref={(node) => registerGlow?.(visual.name, node)}
            r={visual.radius * GLOW_RADIUS_MULTIPLIER}
            fill={color}
            opacity={GLOW_OPACITY}
            filter={`url(#${glowFilterId})`}
            style={{ pointerEvents: "auto", cursor: "pointer" }}
            onMouseEnter={() => onMarkerEnter(visual.name)}
            onMouseLeave={() => onMarkerLeave(visual.name)}
            onClick={() => onMarkerClick(visual.name)}
          />
          <circle
            ref={(node) => registerMarker(visual.name, node)}
            r={visual.radius}
            fill={color}
            style={{ pointerEvents: "auto", cursor: "pointer" }}
            onMouseEnter={() => onMarkerEnter(visual.name)}
            onMouseLeave={() => onMarkerLeave(visual.name)}
            onClick={() => onMarkerClick(visual.name)}
          />
          <text
            ref={(node) => registerLabel?.(visual.name, node)}
            fontSize={LABEL_FONT_SIZE}
            fill={color}
            opacity={isLabelVisible(visual.name) ? LABEL_OPACITY : 0}
            dominantBaseline="middle"
            style={{ transition: `opacity ${LABEL_FADE_DURATION_MS}ms ease` }}
          >
            {visual.name}
          </text>
        </g>
      ))}
    </svg>
  );
}

export function SatelliteBackground({
  overlayIds,
}: {
  overlayIds?: string[];
} = {}) {
  const [viewport, setViewport] = useState<Viewport | null>(null);
  const { resolvedTheme } = useTheme();
  const backgroundColor = resolvedTheme === "light" ? WHITE : BLACK;
  const foregroundColor = resolvedTheme === "light" ? BLACK : WHITE;

  const { satellites, getProgress } = useSatellitePaths();
  const { clipPath } = useOverlayClipPath(overlayIds);
  const showOverlay = Boolean(overlayIds?.length) && clipPath !== null;

  const isFineHoverPointer = useIsFineHoverPointer();
  const [initialLabelPhase, setInitialLabelPhase] = useState(true);
  const [hoveredName, setHoveredName] = useState<string | null>(null);
  const [selectedName, setSelectedName] = useState<string | null>(null);
  const initialLabelTimerStartedRef = useRef(false);
  const initialLabelTimerIdRef = useRef<number | null>(null);
  const pathname = usePathname();

  // Clear any pinned/hovered label whenever the user navigates elsewhere.
  useEffect(() => {
    setHoveredName(null);
    setSelectedName(null);
  }, [pathname]);

  useEffect(() => {
    return () => {
      if (initialLabelTimerIdRef.current !== null) window.clearTimeout(initialLabelTimerIdRef.current);
    };
  }, []);

  const handleMarkerEnter = useCallback(
    (name: string) => {
      if (isFineHoverPointer) setHoveredName(name);
    },
    [isFineHoverPointer],
  );
  const handleMarkerLeave = useCallback(
    (name: string) => {
      if (!isFineHoverPointer) return;
      setHoveredName((current) => (current === name ? null : current));
    },
    [isFineHoverPointer],
  );
  const handleMarkerClick = useCallback(
    (name: string) => {
      if (isFineHoverPointer) return;
      setSelectedName((current) => (current === name ? null : name));
    },
    [isFineHoverPointer],
  );
  const isLabelVisible = useCallback(
    (name: string) => {
      if (initialLabelPhase) return true;
      return isFineHoverPointer ? hoveredName === name : selectedName === name;
    },
    [initialLabelPhase, isFineHoverPointer, hoveredName, selectedName],
  );

  useEffect(() => {
    const updateViewport = () => setViewport({ width: window.innerWidth, height: window.innerHeight });
    updateViewport();
    window.addEventListener("resize", updateViewport);
    return () => window.removeEventListener("resize", updateViewport);
  }, []);

  const assignmentsRef = useRef(new Map<string, PathAssignment>());
  const [proceduralPaths, setProceduralPaths] = useState<Map<string, ProceduralPath>>(new Map());
  useEffect(() => {
    // Keep each satellite's (index, count) pairing stable once assigned, so
    // its path never reshapes mid-lap just because the visible set's
    // ordering shifted between refreshes.
    const names = new Set(satellites.map((satellite) => satellite.name));
    assignmentsRef.current.forEach((_assignment, name) => {
      if (!names.has(name)) assignmentsRef.current.delete(name);
    });
    const count = satellites.length;
    satellites.forEach((satellite, index) => {
      if (!assignmentsRef.current.has(satellite.name)) {
        assignmentsRef.current.set(satellite.name, { index, count });
      }
    });

    if (!viewport) return;
    setProceduralPaths((previous) => {
      const next = buildProceduralPaths(assignmentsRef.current, viewport);
      return proceduralPathsEqual(previous, next) ? previous : next;
    });
  }, [satellites, viewport]);

  const visuals = useMemo(() => buildVisuals(proceduralPaths), [proceduralPaths]);

  // Show every satellite's name for a fixed window the first time paths
  // actually appear on screen, then hand control over to hover/tap.
  useEffect(() => {
    if (initialLabelTimerStartedRef.current) return;
    if (visuals.length === 0) return;
    initialLabelTimerStartedRef.current = true;
    initialLabelTimerIdRef.current = window.setTimeout(() => {
      setInitialLabelPhase(false);
    }, INITIAL_LABEL_DISPLAY_MS);
  }, [visuals]);

  const pathRefs = useRef(new Map<string, SVGPathElement>());
  const backMarkerRefs = useRef(new Map<string, SVGCircleElement>());
  const frontMarkerRefs = useRef(new Map<string, SVGCircleElement>());
  const backGlowRefs = useRef(new Map<string, SVGCircleElement>());
  const frontGlowRefs = useRef(new Map<string, SVGCircleElement>());
  const backLabelRefs = useRef(new Map<string, SVGTextElement>());
  const frontLabelRefs = useRef(new Map<string, SVGTextElement>());
  const lengthCacheRef = useRef(new Map<string, number>());
  const visualsRef = useRef(new Map<string, SatelliteVisual>());

  useEffect(() => {
    lengthCacheRef.current.clear();
  }, [proceduralPaths]);

  useEffect(() => {
    const next = new Map<string, SatelliteVisual>();
    visuals.forEach((visual) => next.set(visual.name, visual));
    visualsRef.current = next;
  }, [visuals]);

  // A single rAF loop drives both layers' markers from the same computed
  // point each frame, so the front (clipped) copy never drifts out of sync
  // with the back copy. Position comes from live time interpolation via
  // SVGGeometryElement.getPointAtLength, not a declarative animateMotion
  // loop, since progress must reflect each satellite's own real-pass-
  // derived duration rather than a fixed animation length.
  useEffect(() => {
    let frame = 0;

    const tick = () => {
      const now = Date.now();
      pathRefs.current.forEach((pathElement, name) => {
        let length = lengthCacheRef.current.get(name);
        if (length === undefined) {
          length = pathElement.getTotalLength();
          lengthCacheRef.current.set(name, length);
        }

        const progress = getProgress(name, now);
        const point = pathElement.getPointAtLength(progress * length);

        const backMarker = backMarkerRefs.current.get(name);
        if (backMarker) {
          backMarker.setAttribute("cx", String(point.x));
          backMarker.setAttribute("cy", String(point.y));
        }
        const frontMarker = frontMarkerRefs.current.get(name);
        if (frontMarker) {
          frontMarker.setAttribute("cx", String(point.x));
          frontMarker.setAttribute("cy", String(point.y));
        }

        const backGlow = backGlowRefs.current.get(name);
        if (backGlow) {
          backGlow.setAttribute("cx", String(point.x));
          backGlow.setAttribute("cy", String(point.y));
        }
        const frontGlow = frontGlowRefs.current.get(name);
        if (frontGlow) {
          frontGlow.setAttribute("cx", String(point.x));
          frontGlow.setAttribute("cy", String(point.y));
        }

        const radius = visualsRef.current.get(name)?.radius ?? BASE_MARKER_RADIUS;
        const labelX = point.x + radius + LABEL_OFFSET_X;
        const labelY = point.y + LABEL_OFFSET_Y;
        // Position via `transform` rather than the `x`/`y` attributes:
        // browsers snap text `x`/`y` to whole pixels for crisper glyph
        // rendering, which makes the label stutter one pixel at a time
        // even while the marker (positioned via cx/cy) glides smoothly.
        // Transforms aren't snapped the same way, so this keeps the label
        // moving in lockstep with the dot.
        const labelTransform = `translate(${labelX}, ${labelY})`;
        const backLabel = backLabelRefs.current.get(name);
        if (backLabel) {
          backLabel.setAttribute("transform", labelTransform);
        }
        const frontLabel = frontLabelRefs.current.get(name);
        if (frontLabel) {
          frontLabel.setAttribute("transform", labelTransform);
        }
      });
      frame = requestAnimationFrame(tick);
    };

    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [getProgress]);

  if (!viewport) return null;

  return (
    <>
      <SatelliteLayer
        visuals={visuals}
        viewport={viewport}
        color={foregroundColor}
        backgroundColor={backgroundColor}
        zIndex={0}
        layerId="back"
        registerPath={(name, node) => {
          if (node) pathRefs.current.set(name, node);
          else pathRefs.current.delete(name);
        }}
        registerMarker={(name, node) => {
          if (node) backMarkerRefs.current.set(name, node);
          else backMarkerRefs.current.delete(name);
        }}
        registerGlow={(name, node) => {
          if (node) backGlowRefs.current.set(name, node);
          else backGlowRefs.current.delete(name);
        }}
        registerLabel={(name, node) => {
          if (node) backLabelRefs.current.set(name, node);
          else backLabelRefs.current.delete(name);
        }}
        isLabelVisible={isLabelVisible}
        onMarkerEnter={handleMarkerEnter}
        onMarkerLeave={handleMarkerLeave}
        onMarkerClick={handleMarkerClick}
      />
      {showOverlay && (
        <SatelliteLayer
          visuals={visuals}
          viewport={viewport}
          color={foregroundColor}
          clipPath={clipPath}
          zIndex={9999}
          layerId="front"
          registerMarker={(name, node) => {
            if (node) frontMarkerRefs.current.set(name, node);
            else frontMarkerRefs.current.delete(name);
          }}
          registerGlow={(name, node) => {
            if (node) frontGlowRefs.current.set(name, node);
            else frontGlowRefs.current.delete(name);
          }}
          registerLabel={(name, node) => {
            if (node) frontLabelRefs.current.set(name, node);
            else frontLabelRefs.current.delete(name);
          }}
          isLabelVisible={isLabelVisible}
          onMarkerEnter={handleMarkerEnter}
          onMarkerLeave={handleMarkerLeave}
          onMarkerClick={handleMarkerClick}
        />
      )}
    </>
  );
}

/**
 * Procedural, full-viewport orbital path generator.
 *
 * This module is intentionally decoupled from any real satellite telemetry
 * (no azimuth/elevation/range inputs). It only needs a stable identity
 * (`seed`), where that identity sits among its concurrent peers
 * (`index`/`count`), and the current viewport size. That makes it reusable
 * for two callers with very different data sources:
 *
 *  - The live renderer: real TLE-derived visibility data picks *which*
 *    satellites are shown and *how long* each stays on screen, but the
 *    on-screen curve shape itself comes from here.
 *  - The offline/no-data fallback (PLAN.md Phase 6, not built yet): can
 *    call this with synthetic seeds (e.g. "FALLBACK-1") and get the same
 *    visually-equivalent full-screen, non-coinciding curves with zero
 *    dependency on live data.
 *
 * Paths are generated directly in real viewport pixels: both endpoints are
 * anchored exactly on the viewport's border (never beyond it), so the
 * entire curve is always on-screen. That matters because the live marker
 * travels linearly along the curve's full length over real time - if large
 * stretches of the curve sat off-screen (as an overshooting curve would),
 * the marker would spend most of its lap invisible before ever entering
 * the viewport. Passing the current `width`/`height` on resize reflows the
 * same deterministic shape (same edge choices/bow proportions) to the new
 * size rather than reseeding, so it never visibly jumps.
 */

export interface ProceduralPathOptions {
  /** Stable identity for this path, e.g. a satellite name. Determines its shape deterministically. */
  seed: string;
  /** This path's position among its concurrent peers (0-based). Used to spread paths apart. */
  index?: number;
  /** Total number of concurrent paths. Used together with `index` to spread paths apart. */
  count?: number;
  /** Current viewport (or logical canvas) width in the same units the consumer renders in. */
  width: number;
  /** Current viewport (or logical canvas) height in the same units the consumer renders in. */
  height: number;
}

export interface ProceduralPath {
  /** A DOM-id-safe identifier derived from the seed, for callers that want to tag elements. */
  id: string;
  /** SVG `d` attribute: a single cubic-bezier curve with both endpoints exactly on the viewport border. */
  d: string;
}

/** FNV-1a string hash, deterministic across runs/platforms. */
function hashString(value: string): number {
  let hash = 0x811c9dc5;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  return hash >>> 0;
}

/** Small, fast, deterministic PRNG (mulberry32) seeded from a 32-bit int. */
function createRandom(seed: number): () => number {
  let state = seed >>> 0;
  return function random() {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function sanitizeId(seed: string, index: number): string {
  const slug = seed
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-+|-+$)/g, "");
  return `sat-path-${slug || "satellite"}-${index}`;
}

/** A point at parameter `u` walking clockwise around the rectangle's perimeter, `u` in [0, 4). */
function perimeterPoint(u: number, width: number, height: number): { x: number; y: number } {
  const wrapped = ((u % 4) + 4) % 4;
  const edge = Math.floor(wrapped);
  const t = wrapped - edge;
  switch (edge) {
    case 0: // top: left -> right
      return { x: t * width, y: 0 };
    case 1: // right: top -> bottom
      return { x: width, y: t * height };
    case 2: // bottom: right -> left
      return { x: (1 - t) * width, y: height };
    default: // left: bottom -> top
      return { x: 0, y: (1 - t) * height };
  }
}

/**
 * Generate a smooth cubic-bezier curve whose two endpoints sit exactly on
 * the viewport's border (never beyond it), so the whole curve - and the
 * marker traveling its full length - stays on-screen. Concurrent paths
 * (same `count`, different `index`) start from evenly-spaced, jittered
 * points around the perimeter so they never coincide, though they may
 * cross.
 */
export function generateProceduralPath(options: ProceduralPathOptions): ProceduralPath {
  const { seed, index = 0, count = 1, width, height } = options;
  const random = createRandom(hashString(`${seed}::${index}::${count}`));

  // Spread starting points evenly around the full perimeter (4 "quarters":
  // top/right/bottom/left), with jitter so no two concurrent paths coincide.
  const spacing = 4 / Math.max(count, 1);
  const startU = spacing * index + random() * spacing * 0.7;
  // Send the end point a substantial distance around the perimeter (never
  // just a nearby point on the same edge) so each path visibly sweeps
  // across the screen rather than clipping a small corner.
  const travel = 1.35 + random() * 1.3; // between ~1.35 and ~2.65 quarters away
  const endU = startU + travel * (random() < 0.5 ? 1 : -1);

  const start = perimeterPoint(startU, width, height);
  const end = perimeterPoint(endU, width, height);

  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const length = Math.max(Math.hypot(dx, dy), 1);
  // Perpendicular unit vector to the start->end chord, for bowing the curve.
  const perpX = -dy / length;
  const perpY = dx / length;

  const sizeReference = Math.min(width, height);
  const bowSign = random() < 0.5 ? -1 : 1;
  const bow1 = sizeReference * (0.1 + random() * 0.16) * bowSign;
  const bow2 = sizeReference * (0.1 + random() * 0.16) * (random() < 0.35 ? -bowSign : bowSign);

  const c1x = start.x + dx * 0.32 + perpX * bow1;
  const c1y = start.y + dy * 0.32 + perpY * bow1;
  const c2x = start.x + dx * 0.68 + perpX * bow2;
  const c2y = start.y + dy * 0.68 + perpY * bow2;

  const round = (value: number) => Math.round(value * 10) / 10;
  const d =
    `M ${round(start.x)} ${round(start.y)} ` +
    `C ${round(c1x)} ${round(c1y)}, ${round(c2x)} ${round(c2y)}, ${round(end.x)} ${round(end.y)}`;

  return {
    id: sanitizeId(seed, index),
    d,
  };
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

interface ApiPathPoint {
  timestamp: string;
}

interface ApiSatellite {
  name: string;
  current: ApiPathPoint;
  path: ApiPathPoint[];
}

interface VisibilityResponse {
  satellites: ApiSatellite[];
}

function isApiPathPoint(value: unknown): value is ApiPathPoint {
  if (!value || typeof value !== "object") return false;
  const point = value as Partial<ApiPathPoint>;
  return typeof point.timestamp === "string" && Number.isFinite(Date.parse(point.timestamp));
}

function isApiSatellite(value: unknown): value is ApiSatellite {
  if (!value || typeof value !== "object") return false;
  const satellite = value as Partial<ApiSatellite>;
  return (
    typeof satellite.name === "string" &&
    isApiPathPoint(satellite.current) &&
    Array.isArray(satellite.path) &&
    satellite.path.length > 0 &&
    satellite.path.every(isApiPathPoint)
  );
}

export interface TrackedSatellite {
  name: string;
}

const SYNTHETIC_SATELLITES: TrackedSatellite[] = Array.from({ length: 3 }, (_, index) => ({
  name: `DEMO ORBIT ${index + 1}`,
}));

interface SatelliteTiming {
  /** Wall-clock time this satellite was first observed in the visible set. */
  enteredAt: number;
  /** How long one lap across its on-screen path should take, derived from real pass timing. */
  durationMs: number;
}

interface UseSatellitePathsOptions {
  intervalMs?: number;
  observer?: { lat: number; lon: number };
}

const DEFAULT_INTERVAL_MS = 5 * 60 * 1000;
// Fallback lap duration if a satellite's sampled timeline is somehow too short to trust.
const DEFAULT_DURATION_MS = 10 * 60 * 1000;
const MIN_TRUSTED_SPAN_MS = 30 * 1000;

function getVisibilityUrl(observer?: { lat: number; lon: number }): string {
  if (!observer) return "/api/visibility";
  const params = new URLSearchParams({ lat: String(observer.lat), lon: String(observer.lon) });
  return `/api/visibility?${params}`;
}

/**
 * Tracks which satellites are currently visible (for path assignment) and,
 * for each, how far through its on-screen "lap" it should currently be.
 *
 * Deliberately does not expose azimuth/elevation/screen-projected geometry
 * any more: the rendered path shape is now a procedural curve (see
 * `procedural-path.ts`), not a literal projection of the sky position. Real
 * data still determines *which* satellites appear and, via each one's
 * sampled timeline span, roughly *how long* it stays on screen per lap.
 */
export function useSatellitePaths(options: UseSatellitePathsOptions = {}) {
  const { intervalMs = DEFAULT_INTERVAL_MS, observer } = options;
  const [satellites, setSatellites] = useState<TrackedSatellite[]>(SYNTHETIC_SATELLITES);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const timingRef = useRef(new Map<string, SatelliteTiming>());

  const refresh = useCallback(async (signal: AbortSignal) => {
    const response = await fetch(getVisibilityUrl(observer), { signal, cache: "no-store" });
    if (!response.ok) throw new Error(`Visibility request failed (${response.status})`);
    const data = (await response.json()) as Partial<VisibilityResponse>;
    if (!Array.isArray(data.satellites) || !data.satellites.every(isApiSatellite)) {
      throw new Error("Visibility response has an invalid sampled-path shape");
    }

    const now = Date.now();
    const seenNames = new Set<string>();

    for (const satellite of data.satellites) {
      seenNames.add(satellite.name);

      const first = Date.parse(satellite.path[0].timestamp);
      const last = Date.parse(satellite.path[satellite.path.length - 1].timestamp);
      const span = last - first;
      const durationMs = Number.isFinite(span) && span > MIN_TRUSTED_SPAN_MS ? span : DEFAULT_DURATION_MS;

      const existing = timingRef.current.get(satellite.name);
      if (existing) {
        // Keep the original entry time so an already-animating satellite's
        // lap progress never jumps; just keep its duration estimate fresh.
        existing.durationMs = durationMs;
      } else {
        timingRef.current.set(satellite.name, { enteredAt: now, durationMs });
      }
    }

    for (const name of Array.from(timingRef.current.keys())) {
      if (!seenNames.has(name)) timingRef.current.delete(name);
    }

    setSatellites(data.satellites.map((satellite) => ({ name: satellite.name })));
    setError(null);
  }, [observer]);

  useEffect(() => {
    let active = true;
    let controller = new AbortController();

    const run = async () => {
      controller.abort();
      controller = new AbortController();
      try {
        await refresh(controller.signal);
        if (active) setLoading(false);
      } catch (cause) {
        if (active && cause instanceof Error && cause.name !== "AbortError") {
          setError(cause.message);
          setLoading(false);
        }
      }
    };

    void run();
    const interval = window.setInterval(() => void run(), intervalMs);
    return () => {
      active = false;
      controller.abort();
      window.clearInterval(interval);
    };
  }, [intervalMs, refresh]);

  /** Normalized, looping [0, 1) progress for a satellite's current lap, driven purely by wall clock. */
  const getProgress = useCallback((name: string, now: number): number => {
    const timing = timingRef.current.get(name);
    if (!timing || timing.durationMs <= 0) return 0;
    const elapsed = now - timing.enteredAt;
    if (elapsed <= 0) return 0;
    return (elapsed % timing.durationMs) / timing.durationMs;
  }, []);

  return {
    satellites,
    getProgress,
    loading,
    error,
  };
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

function buildClipPath(elements: HTMLElement[]): string | null {
  const segments: string[] = [];
  for (const element of elements) {
    const rect = element.getBoundingClientRect();
    if (rect.width <= 0 || rect.height <= 0) continue;
    const left = rect.left;
    const top = rect.top;
    const right = rect.right;
    const bottom = rect.bottom;
    segments.push(`M ${left} ${top} H ${right} V ${bottom} H ${left} Z`);
  }
  if (segments.length === 0) return null;
  return `path(evenodd, "${segments.join(" ")}")`;
}

export function useOverlayClipPath(overlayIds?: string[]): {
  clipPath: string | null;
} {
  const [clipPath, setClipPath] = useState<string | null>(null);
  const elementsRef = useRef<HTMLElement[]>([]);
  const frameRef = useRef<number | null>(null);

  const scheduleRecompute = useCallback(() => {
    if (frameRef.current !== null) return;
    frameRef.current = requestAnimationFrame(() => {
      frameRef.current = null;
      setClipPath(buildClipPath(elementsRef.current));
    });
  }, []);

  const cancelPending = useCallback(() => {
    if (frameRef.current !== null) {
      cancelAnimationFrame(frameRef.current);
      frameRef.current = null;
    }
  }, []);

  useEffect(() => {
    if (!overlayIds || overlayIds.length === 0) {
      cancelPending();
      elementsRef.current = [];
      setClipPath(null);
      return;
    }

    let resizeObserver: ResizeObserver | null = null;

    const resolveElements = () => {
      const elements = overlayIds
        .map((id) => document.getElementById(id))
        .filter((element): element is HTMLElement => element !== null);
      const changed =
        elements.length !== elementsRef.current.length ||
        elements.some((element, index) => element !== elementsRef.current[index]);
      if (!changed) return;

      elementsRef.current = elements;
      resizeObserver?.disconnect();
      resizeObserver = new ResizeObserver(() => scheduleRecompute());
      for (const element of elements) resizeObserver.observe(element);
      scheduleRecompute();
    };

    resolveElements();

    const mutationObserver = new MutationObserver(() => resolveElements());
    mutationObserver.observe(document.body, { childList: true, subtree: true });

    const handleScroll = () => scheduleRecompute();
    window.addEventListener("scroll", handleScroll, { capture: true, passive: true });
    window.addEventListener("resize", handleScroll);

    return () => {
      mutationObserver.disconnect();
      resizeObserver?.disconnect();
      window.removeEventListener("scroll", handleScroll, { capture: true });
      window.removeEventListener("resize", handleScroll);
      cancelPending();
      elementsRef.current = [];
      setClipPath(null);
    };
  }, [overlayIds, scheduleRecompute, cancelPending]);

  return { clipPath };
}
